mapper.select:
SELECT fingerprint, event_ids::text AS event_ids, settled_input_event_ids::text AS settled_input_event_ids, handoff_completed
FROM session_input_requests
WHERE organization_uuid = #{session.OrganizationUUID}
  AND workspace_uuid = #{session.WorkspaceUUID}
  AND session_uuid = #{session.UUID}
  AND request_key = #{request.Key}

mapper.update:
UPDATE session_input_requests SET handoff_completed = true
WHERE organization_uuid = #{session.OrganizationUUID}
  AND workspace_uuid = #{session.WorkspaceUUID}
  AND session_uuid = #{session.UUID}
  AND request_key = #{request.Key}
  AND fingerprint = #{request.Fingerprint}
